#!/usr/bin/env node
// ═══════════════════════════════════════════════════════════════════════════
// REBNY RLS COMPLIANCE REPORTER v3 — coverage / assertion reporter over the CANONICAL CONTRACTS
//
// This script decides NOTHING about provider fields, enum members, required / conditional rules or
// distribution semantics. It reads the canonical authorities and reports how the CRM surfaces cover
// them and whether any surface still claims something the authorities do not carry.
//
//   COTALITY LIVE CONTRACT  → lib/cotality/live-contract.ts (the dated live pulls, regenerated by
//                             `npm run cotality:compile`): field existence, enum members.
//   REBNY / UCBA            → lib/compliance/rebny-ucba-rules.ts (REBNY_UCBA_RULES): required,
//                             conditional and removed fields, exclusive agreements.
//   MALLAN                  → lib/listings/mallan-form-contract.ts: MALLAN_INTERNAL_KEYS (the
//                             Mallan-only facts the write path persists), aliasToCanonical.
//   legacy phantom names    → lib/compliance/legacy-form-keys.ts (never on the live resource).
//
// Mallan UI configuration (NOT authority — form-control classification only):
//   data/rls-field-aliases.json   form-control id → the field it collects (every target must be a
//                                 live field or a declared Mallan-internal key; anything else is a
//                                 Mallan control and is reported)
//   data/rls-internal-only.json   form-control ids that are UI (buttons, search widgets) — not facts
//
// The REBNY CSVs (data/rebny-rls-property-*.csv) are historical reference material and are NOT read.
// RESO is vocabulary only: there is no RESO→RLS rename table and no CSV-derived rule set here.
//
// Runs under tsx (`npm run rls:validate` = `tsx scripts/validate-rls-compliance.js`) so the
// TypeScript contracts load directly. Usage: [--verbose] [--html]. Exit 0 = no errors and no UNKNOWN
// elements; 1 otherwise.
// ═══════════════════════════════════════════════════════════════════════════

const fs = require('fs');
const path = require('path');
const { parse: parseHTML } = require('node-html-parser');

const VERBOSE = process.argv.includes('--verbose');
const REPO_ROOT = path.resolve(__dirname, '..');
const CRM = path.resolve(REPO_ROOT, 'public', 'crm');

// ── Canonical contracts ──────────────────────────────────────────────────────
const liveContract = require(path.join(REPO_ROOT, 'lib', 'cotality', 'live-contract'));
const { REBNY_UCBA_RULES } = require(path.join(REPO_ROOT, 'lib', 'compliance', 'rebny-ucba-rules'));
const { MALLAN_INTERNAL_KEYS, MALLAN_FORM_CONTRACT } = require(path.join(REPO_ROOT, 'lib', 'listings', 'mallan-form-contract'));
const { LEGACY_MALLAN_FORM_CONTROL_KEYS } = require(path.join(REPO_ROOT, 'lib', 'compliance', 'legacy-form-keys'));

const LIVE_FIELDS = liveContract.LIVE_PROPERTY_FIELDS;               // Set<string>
const liveEnumMembers = liveContract.liveEnumMembers;                // (field) => string[] | null
const INTERNAL_KEYS = new Set(MALLAN_INTERNAL_KEYS);
const PHANTOMS = LEGACY_MALLAN_FORM_CONTROL_KEYS;                    // Set<string>
const isCanonical = (name) => LIVE_FIELDS.has(name) || INTERNAL_KEYS.has(name);
const isMallanDecisionKey = (name) => name.startsWith('_');

// ── Mallan UI configuration (form-control classification, validated against the contracts) ──
const RAW_ALIASES = JSON.parse(fs.readFileSync(path.join(REPO_ROOT, 'data', 'rls-field-aliases.json'), 'utf8'));
const INTERNAL_ONLY_IDS = new Set(JSON.parse(fs.readFileSync(path.join(REPO_ROOT, 'data', 'rls-internal-only.json'), 'utf8')));
const FIELD_ALIASES = {};
const ALIAS_NOTES = [];
for (const [id, target] of Object.entries(RAW_ALIASES)) {
  if (PHANTOMS.has(target)) { ALIAS_NOTES.push(`alias "${id}" → "${target}" names a legacy phantom (never on the live resource) — alias refused`); continue; }
  if (isCanonical(target)) FIELD_ALIASES[id] = target;
  else ALIAS_NOTES.push(`alias "${id}" → "${target}": neither a live Cotality field nor a declared Mallan-internal key — the control is a Mallan fact under its own id`);
}

// ── Files ────────────────────────────────────────────────────────────────────
const FILE_CONFIG = {
  saleForm:     { path: path.join(CRM, 'SALE-FORM-REDESIGN.html'),     category: 'submission', type: 'sale' },
  rentalForm:   { path: path.join(CRM, 'RENTAL-FORM-REDESIGN.html'),   category: 'submission', type: 'rental' },
  saleViewer:   { path: path.join(CRM, 'SALE-FORM-WITH-TOOLS.html'),   category: 'viewer' },
  rentalViewer: { path: path.join(CRM, 'RENTAL-FORM-WITH-TOOLS.html'), category: 'viewer' },
  search:       { path: path.join(CRM, 'index-built.html'),            category: 'search' },
};
const EXTRA_FILES = {
  crm:        path.join(CRM, 'index.html'),
  buyerDeal:  path.join(CRM, 'BUYER-DEAL-FORM.html'),
  tenantDeal: path.join(CRM, 'TENANT-DEAL-FORM.html'),
};
const SOURCE_MODULE = path.join(CRM, 'js', 'core', 'reso-field-map.js');
const BROWSER_JS_DIR = path.join(CRM, 'js');
/** The server modules that implement the distribution gates (assertion targets, read-only). */
const GATE_MODULES = {
  mapper:   path.join(REPO_ROOT, 'lib', 'idx', 'trestle-mapper.ts'),
  readGate: path.join(REPO_ROOT, 'lib', 'compliance', 'idx-display-gate.ts'),
  writeGate: path.join(REPO_ROOT, 'lib', 'compliance', 'rls-enforcement.ts'),
};

// Mallan-side classification of submission surfaces (not provider facts)
const FORM_PREFIXES = ['sale', 'rental', 'bldg', 'search', 'oh', 'crm', 'comm'];
const RENTAL_ONLY = new Set(['NetMonthlyRent', 'AvailabilityDate', 'LeaseType', 'MinLeaseMonths']);
const SALE_ONLY = new Set(['FlipTax', 'FlipTaxType', 'MaximumFinancingAmount', 'MaximumFinancingPercent', 'PercentOfCommonElements', 'TaxDeductionPercent']);
/** Provider classification fields the SERVER derives from the Mallan form keys (lib/crm/listing-form-mapping.ts). */
const SERVER_DERIVED = new Set(['PropertyType', 'PropertySubType', 'CommonInterest', 'StructureType', 'View', 'BuildingFeatures', 'MoveInCosts', 'OngoingFees', 'TenantPays']);
const CLOSING_ONLY_FIELDS = new Set(['BuyerAgentMlsId', 'BuyerAgentDirectPhone', 'BuyerAgentEmail', 'BuyerAgentFullName', 'BuyerAgentStateLicense', 'BuyerAgentRLSParticipantYN', 'BuyerOfficeName', 'BuyerOfficePhone', 'ClosePrice', 'PurchaseContractDate']);

// ── Results ──────────────────────────────────────────────────────────────────
const results = {
  1:  { name: 'PICKLIST VALUES (live enums)',      errors: [], warnings: [] },
  2:  { name: 'REQUIRED FIELDS (REBNY/UCBA)',       errors: [], warnings: [] },
  3:  { name: 'FIELD-NAME CLAIMS (canonical)',      errors: [], warnings: [] },
  4:  { name: 'DISTRIBUTION GATES (live fields)',   errors: [], warnings: [] },
  5:  { name: 'FIELD MAP INTEGRITY (annotation)',   errors: [], warnings: [] },
  6:  { name: '(REMOVED)',                          errors: [], warnings: [] },
  7:  { name: 'CONDITIONAL RULES (REBNY/UCBA)',     errors: [], warnings: [], missing: [] },
  8:  { name: 'ROLE MASKING',                       errors: [], warnings: [] },
  9:  { name: 'CANONICAL COVERAGE',                 errors: [], warnings: [] },
  10: { name: 'VIEWER LOCKDOWN',                    errors: [], warnings: [] },
};
function error(section, msg) { results[section].errors.push(msg); }
function warn(section, msg)  { results[section].warnings.push(msg); }
function missing(msg)        { results[7].missing.push(msg); }
function log(msg) { if (VERBOSE) console.log('  ' + msg); }

const classification = { rlsBound: 0, internal: 0, unknown: 0, byFile: {}, byLayer: { 0: 0, 1: 0, 2: 0, 3: 0, 4: 0 } };

function loadFile(p) { try { return fs.readFileSync(p, 'utf8'); } catch { return null; } }
function loadDOM(p) { const raw = loadFile(p); if (raw === null) return null; return { dom: parseHTML(raw), raw }; }
function shortName(p) { return path.basename(p); }
/** Active code lines only (line comments and block-comment lines dropped). */
function codeLines(src) { return src.split(/\r?\n/).filter((l) => !/^\s*(\/\/|\*|\/\*|<!--)/.test(l)); }
function walk(dir) { const out = []; for (const n of fs.readdirSync(dir)) { const p = path.join(dir, n); if (fs.statSync(p).isDirectory()) out.push(...walk(p)); else if (/\.(js|html)$/.test(n)) out.push(p); } return out; }

// ═══════════════════════════════════════════════════════════════════════════
// ELEMENT RESOLUTION — classify a form control against the canonical universe
//   0: data-rls-ignore="true" / data-mallan-field   → INTERNAL (Mallan control; its live member, if any, is server-derived)
//   1: data-rls-field="X"                            → BOUND to X (X must be canonical — Section 3 reports otherwise)
//   2: internal-only id / exact canonical name / alias
//   3: prefix normalization (sale/rental/bldg/TH …) then 2 again
//   4: UNKNOWN (hard error)
// ═══════════════════════════════════════════════════════════════════════════
const MALLAN_GROUPS = new Set(); // name attributes of radio / checkbox groups where any member is a Mallan control
function resolveElement(el) {
  const groupName = (el.getAttribute('name') || '').trim();
  if (el.getAttribute('data-rls-ignore') === 'true' || el.getAttribute('data-mallan-field') || (groupName && MALLAN_GROUPS.has(groupName))) { classification.byLayer[0]++; return { internal: true, layer: 0 }; }
  const rlsAttr = el.getAttribute('data-rls-field');
  if (rlsAttr) { classification.byLayer[1]++; return { field: rlsAttr, layer: 1 }; }
  const identifier = ((el.getAttribute('id') || '').trim()) || ((el.getAttribute('name') || '').trim());
  if (!identifier) return { internal: true, layer: 0 };
  if (INTERNAL_ONLY_IDS.has(identifier)) { classification.byLayer[2]++; return { internal: true, layer: 2 }; }
  if (isCanonical(identifier)) { classification.byLayer[2]++; return { field: identifier, layer: 2 }; }
  if (FIELD_ALIASES[identifier]) { classification.byLayer[2]++; return { field: FIELD_ALIASES[identifier], layer: 2 }; }
  if (RAW_ALIASES[identifier]) { classification.byLayer[2]++; return { internal: true, layer: 2 }; } // alias target is a Mallan fact (see ALIAS_NOTES)

  let remainder = identifier;
  for (const prefix of FORM_PREFIXES) {
    if (identifier.toLowerCase().startsWith(prefix) && identifier.length > prefix.length) {
      const after = identifier.substring(prefix.length);
      if (/^[A-Z]/.test(after)) {
        if (prefix === 'bldg' && isCanonical('Building' + after)) { classification.byLayer[3]++; return { field: 'Building' + after, layer: 3 }; }
        remainder = after; break;
      }
    }
  }
  if (remainder.startsWith('Bldg') && remainder.length > 4 && /^[A-Z]/.test(remainder[4])) {
    const bName = 'Building' + remainder.substring(4);
    if (isCanonical(bName)) { classification.byLayer[3]++; return { field: bName, layer: 3 }; }
    remainder = remainder.substring(4);
  }
  if (remainder.startsWith('TH') && remainder.length > 2 && /^[A-Z]/.test(remainder[2])) remainder = remainder.substring(2);

  if (INTERNAL_ONLY_IDS.has(remainder)) { classification.byLayer[3]++; return { internal: true, layer: 3 }; }
  if (PHANTOMS.has(remainder)) { classification.byLayer[3]++; return { internal: true, layer: 3, phantomControl: remainder }; } // a Mallan control named after a retired key
  if (isCanonical(remainder)) { classification.byLayer[3]++; return { field: remainder, layer: 3 }; }
  if (FIELD_ALIASES[remainder]) { classification.byLayer[3]++; return { field: FIELD_ALIASES[remainder], layer: 3 }; }
  if (RAW_ALIASES[remainder]) { classification.byLayer[3]++; return { internal: true, layer: 3 }; }
  classification.byLayer[4]++;
  return { unknown: true, identifier, layer: 4 };
}

function passA_Discovery() {
  console.log('\n  PASS A: Discovery — classifying all form controls against the canonical universe...');
  const fileElements = {};
  for (const [fileKey, config] of Object.entries(FILE_CONFIG)) {
    const loaded = loadDOM(config.path); if (!loaded) continue;
    const { dom, raw } = loaded; const fname = shortName(config.path);
    for (const el of dom.querySelectorAll('input[type="radio"], input[type="checkbox"]')) {
      const n = (el.getAttribute('name') || '').trim();
      if (n && (el.getAttribute('data-rls-ignore') === 'true' || el.getAttribute('data-mallan-field'))) MALLAN_GROUPS.add(n);
    }
    const elements = []; const seen = new Set();
    for (const el of dom.querySelectorAll('input, select, textarea')) {
      const identifier = ((el.getAttribute('id') || '').trim()) || ((el.getAttribute('name') || '').trim());
      if (!identifier || seen.has(identifier)) continue; seen.add(identifier);
      elements.push({ el, identifier, result: resolveElement(el), elType: el.getAttribute('type') || el.tagName.toLowerCase() });
    }
    for (const r of dom.querySelectorAll('input[type="radio"]')) {
      const rName = (r.getAttribute('name') || '').trim();
      if (!rName || seen.has(rName)) continue; seen.add(rName);
      elements.push({ el: r, identifier: rName, result: resolveElement(r), elType: 'radio' });
    }
    const stats = { rlsBound: 0, internal: 0, unknown: 0, unknownIds: [] };
    for (const { result, identifier } of elements) {
      if (result.field) { stats.rlsBound++; classification.rlsBound++; }
      else if (result.internal) { stats.internal++; classification.internal++; }
      else if (result.unknown) { stats.unknown++; stats.unknownIds.push(identifier); classification.unknown++; }
    }
    classification.byFile[fname] = stats;
    fileElements[fileKey] = { elements, dom, raw, fname, config };
    log(`${fname}: ${elements.length} controls — ${stats.rlsBound} bound, ${stats.internal} Mallan-internal, ${stats.unknown} unknown`);
  }
  return fileElements;
}

// ═══════════════════════════════════════════════════════════════════════════
// SECTION 1: PICKLIST VALUES — every option / checkbox value bound to a live enum field is a live member
// ═══════════════════════════════════════════════════════════════════════════
function validatePicklists(fileElements) {
  console.log('\n  Section 1: Picklist values (live Cotality enums) ...');
  const SKIP_VALUES = new Set(['', 'Select', 'select', '--', 'Choose', 'choose', 'All', 'Any']);
  for (const data of Object.values(fileElements)) {
    const { dom, fname, config } = data;
    if (config.category === 'search') continue;
    for (const sel of dom.querySelectorAll('select')) {
      const r = resolveElementQuiet(sel); if (!r.field) continue;
      const members = liveEnumMembers(r.field); if (!members) continue;
      const set = new Set(members);
      const values = [];
      for (const opt of sel.querySelectorAll('option')) {
        const val = (opt.getAttribute('value') || '').trim();
        if (SKIP_VALUES.has(val)) continue; values.push(val);
        if (!set.has(val)) error(1, `${fname}: <select> "${r.field}": value "${val}" is not a live Cotality ${r.field} member`);
      }
      if (config.category === 'submission') {
        const miss = members.filter((m) => !values.includes(m));
        if (miss.length > 0) warn(1, `${fname}: "${r.field}": ${miss.length} live member${miss.length > 1 ? 's' : ''} not offered: ${miss.slice(0, 5).join(', ')}${miss.length > 5 ? '…' : ''}`);
      }
    }
    for (const cb of dom.querySelectorAll('input[type="checkbox"], input[type="radio"]')) {
      const r = resolveElementQuiet(cb); if (!r.field) continue;
      const members = liveEnumMembers(r.field); if (!members) continue;
      const val = (cb.getAttribute('value') || '').trim();
      if (val && !SKIP_VALUES.has(val) && !members.includes(val)) error(1, `${fname}: ${cb.getAttribute('type')} "${r.field}": value "${val}" is not a live Cotality ${r.field} member`);
    }
  }
}
// resolution without touching the classification counters
function resolveElementQuiet(el) { const snap = { ...classification.byLayer }; const r = resolveElement(el); Object.assign(classification.byLayer, snap); return r; }

// ═══════════════════════════════════════════════════════════════════════════
// SECTION 2: REQUIRED FIELDS — REBNY_UCBA_RULES.requiredFields.agentSubmitted is collectable by each submission form
// ═══════════════════════════════════════════════════════════════════════════
function validateRequiredFields(fileElements) {
  console.log('\n  Section 2: Required fields (REBNY_UCBA_RULES.requiredFields) ...');
  const systemGenerated = new Set(REBNY_UCBA_RULES.requiredFields.systemGenerated);
  for (const data of Object.values(fileElements)) {
    const { elements, raw, fname, config } = data;
    if (config.category !== 'submission') continue;
    const skip = config.type === 'sale' ? RENTAL_ONLY : SALE_ONLY;
    const covered = new Set(elements.filter((e) => e.result.field).map((e) => e.result.field));
    for (const fieldName of REBNY_UCBA_RULES.requiredFields.agentSubmitted) {
      if (systemGenerated.has(fieldName) || skip.has(fieldName)) continue;
      if (isMallanDecisionKey(fieldName) || SERVER_DERIVED.has(fieldName)) continue; // derived by the server from the Mallan form keys
      if (covered.has(fieldName)) continue;
      const inJS = raw.includes(fieldName);
      if (CLOSING_ONLY_FIELDS.has(fieldName)) { if (!inJS) warn(2, `${fname}: closing-only field "${fieldName}" not found (OK if only at closing)`); }
      else if (inJS) log(`${fname}: "${fieldName}" — no bound control but referenced in the form script`);
      else error(2, `${fname}: REBNY required field "${fieldName}" — no bound control and no script reference`);
    }
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// SECTION 3: FIELD-NAME CLAIMS — every field name a surface claims is canonical; no phantom in active code
// ═══════════════════════════════════════════════════════════════════════════
function validateFieldNameClaims(fileElements) {
  console.log('\n  Section 3: Field-name claims (live contract + Mallan-internal keys) ...');
  const files = [...Object.values(FILE_CONFIG).map((c) => c.path), ...Object.values(EXTRA_FILES), SOURCE_MODULE, ...walk(BROWSER_JS_DIR)];
  const phantomRe = new RegExp('(?<![A-Za-z0-9_$])(' + [...PHANTOMS].join('|') + ')(?![A-Za-z0-9_$])');
  for (const filePath of files) {
    const content = loadFile(filePath); if (!content) continue;
    const fname = shortName(filePath);
    for (const m of content.matchAll(/data-(rls|reso|mallan)-field="([^"']+)"/g)) {
      const [, kind, name] = m;
      if (/[+'"]/.test(name)) continue; // template expression, not a literal claim
      if (PHANTOMS.has(name)) { error(3, `${fname}: data-${kind}-field="${name}" names a legacy phantom (never on the live resource)`); continue; }
      if (kind === 'mallan') continue; // a Mallan control; the server derives the live member when one exists
      if (!isCanonical(name)) error(3, `${fname}: data-${kind}-field="${name}" is neither a live Cotality field nor a declared Mallan-internal key`);
    }
    codeLines(content).forEach((line, i) => {
      const m = line.match(phantomRe);
      if (m) error(3, `${fname}:${i + 1}: active code names the legacy phantom "${m[1]}" — the live field / Mallan key must be used`);
    });
  }
  for (const data of Object.values(fileElements)) {
    for (const { result, identifier } of data.elements) {
      if (result.field && !isCanonical(result.field)) error(3, `${data.fname}: control "${identifier}" resolves to "${result.field}", which is not canonical`);
      if (result.phantomControl) warn(3, `${data.fname}: control "${identifier}" is named after the retired "${result.phantomControl}" — treated as a Mallan control (rename when convenient)`);
    }
  }
  for (const note of ALIAS_NOTES) warn(3, `rls-field-aliases.json: ${note}`);
  for (const id of INTERNAL_ONLY_IDS) if (LIVE_FIELDS.has(id)) warn(3, `rls-internal-only.json: "${id}" is also a live Cotality field name — the control is treated as Mallan UI`);
}

// ═══════════════════════════════════════════════════════════════════════════
// SECTION 4: DISTRIBUTION GATES — the live fields the gates run on, asserted against the contract
// (verified live 2026-09-06: InternetEntireListingDisplayYN / InternetAddressDisplayYN Boolean, provider-gated
//  (null on every sampled row, $filter → 400 "suppressed (provider Level)"); InternetAutomatedValuationDisplayYN /
//  InternetConsumerCommentYN Boolean per-row; Permission String enum ('IDX' on every live row; 'Private' live
//  member, 0 rows); SyndicateTo collection (null on every live row); StandardStatus enum with ComingSoon / Closed.
//  IDXEntireListingDisplayYN, SyndicateYN, ParticipantOnlyYN → 400 "Could not find a property".)
// ═══════════════════════════════════════════════════════════════════════════
const GATE_FIELDS = {
  'IDX / internet display (master, provider-gated)': { field: 'InternetEntireListingDisplayYN' },
  'address display (provider-gated)':                { field: 'InternetAddressDisplayYN' },
  'AVM display (per-row)':                           { field: 'InternetAutomatedValuationDisplayYN' },
  'consumer comment (per-row)':                      { field: 'InternetConsumerCommentYN' },
  'participant-only / owner opt-out (provider fact)': { field: 'Permission', members: ['Private', 'IDX'] },
  'syndication (provider collection)':               { field: 'SyndicateTo', enum: true },
  'coming soon / closed (status)':                   { field: 'StandardStatus', members: ['ComingSoon', 'Closed'] },
};
/** Mallan business facts with NO provider field — they stay Mallan-internal by design. */
const MALLAN_ONLY_GATE_FACTS = ['_mallanPermission', 'owner_opt_out', 'participant_only', 'idx_display_yn'];

function validateDistributionGates(fileElements) {
  console.log('\n  Section 4: Distribution gates (live fields + Mallan decisions) ...');
  for (const [label, spec] of Object.entries(GATE_FIELDS)) {
    if (!LIVE_FIELDS.has(spec.field)) { error(4, `${label}: "${spec.field}" is not on the live Cotality contract (pull ${liveContract.COTALITY_CONTRACT_PULLED_AT})`); continue; }
    if (spec.enum && !liveEnumMembers(spec.field)) error(4, `${label}: "${spec.field}" has no live enum members on the contract`);
    for (const m of spec.members || []) if (!(liveEnumMembers(spec.field) || []).includes(m)) error(4, `${label}: live ${spec.field} has no member "${m}"`);
    log(`${label}: ${spec.field} — on the live contract`);
  }
  const contractSrc = loadFile(path.join(REPO_ROOT, 'lib', 'listings', 'mallan-form-contract.ts')) || '';
  if (!contractSrc.includes("'_mallanPermission'")) error(4, 'mallan-form-contract.ts: the Mallan permission decision key _mallanPermission is not declared');
  for (const [key, p] of Object.entries(GATE_MODULES)) {
    const src = loadFile(p); if (!src) { error(4, `${key}: gate module missing (${shortName(p)})`); continue; }
    const code = codeLines(src).join('\n');
    for (const phantom of PHANTOMS) {
      if (new RegExp('(?<![A-Za-z0-9_$])' + phantom + '(?![A-Za-z0-9_$])').test(code)) error(4, `${shortName(p)}: active code names the legacy phantom "${phantom}"`);
    }
    // the read gate consumes the Mallan DTO (compliance.internetEntireListingDisplayYN); the mapper reads the live field
    if (key !== 'writeGate' && !/InternetEntireListingDisplayYN/i.test(code)) error(4, `${shortName(p)}: the master display gate InternetEntireListingDisplayYN is not referenced`);
  }
  // Browser gate consumers read the Mallan DTO keys (never provider names they cannot verify)
  const search = fileElements.search;
  if (search && search.raw) {
    if (!search.raw.includes('checkListingCompliance')) error(4, 'index-built.html: checkListingCompliance function NOT FOUND');
    for (const key of ['ownerOptOut', 'participantOnly', 'idxDisplay', 'internetDisplayYN', 'ComingSoon']) {
      if (!search.raw.includes(key)) error(4, `index-built.html: the browser gate consumer no longer references the DTO key "${key}"`);
    }
  }
  for (const key of ['saleForm', 'rentalForm']) {
    const data = fileElements[key]; if (!data) continue;
    if (!data.raw.includes('SyndicateTo')) warn(4, `${data.fname}: no reference to the live syndication collection SyndicateTo`);
  }
  log(`Mallan-only gate facts (no provider field by design): ${MALLAN_ONLY_GATE_FACTS.join(', ')}`);
}

// ═══════════════════════════════════════════════════════════════════════════
// SECTION 5: FIELD MAP INTEGRITY — RESO_FIELD_MAP is display annotation: live values, source == built
// ═══════════════════════════════════════════════════════════════════════════
function extractMapEntries(content) {
  const start = content.indexOf('RESO_FIELD_MAP'); if (start < 0) return null;
  const open = content.indexOf('{', start); let depth = 0, end = open;
  for (let i = open; i < content.length && i < open + 20000; i++) { if (content[i] === '{') depth++; if (content[i] === '}') { depth--; if (depth === 0) { end = i + 1; break; } } }
  const block = content.substring(open, end);
  const entries = {};
  for (const m of block.matchAll(/^\s*([A-Za-z_]+):\s*'([^']+)'/gm)) entries[m[1]] = m[2];
  return entries;
}
function validateFieldMapIntegrity() {
  console.log('\n  Section 5: RESO_FIELD_MAP integrity (display annotation only) ...');
  const sourceContent = loadFile(SOURCE_MODULE); const builtContent = loadFile(FILE_CONFIG.search.path);
  if (!sourceContent) { error(5, 'reso-field-map.js not found'); return; }
  if (!builtContent) { error(5, 'index-built.html not found'); return; }
  if (!sourceContent.includes('DISPLAY-ANNOTATION VOCABULARY, NOT PROVIDER AUTHORITY')) error(5, 'reso-field-map.js: the annotation-only declaration is missing');
  if (/function\s+map[A-Za-z]*\(|toRESO|fromRESO|mapListingTo|mapRESOTo/.test(sourceContent)) error(5, 'reso-field-map.js: contains a mapping function — the map must stay annotation-only');
  const src = extractMapEntries(sourceContent); const built = extractMapEntries(builtContent);
  if (!src) { error(5, 'reso-field-map.js: RESO_FIELD_MAP not found'); return; }
  if (!built) { error(5, 'index-built.html: RESO_FIELD_MAP not found (build drift)'); return; }
  for (const [k, v] of Object.entries(src)) {
    if (!v.startsWith('computed:') && !LIVE_FIELDS.has(v)) error(5, `reso-field-map.js: ${k} → "${v}" is not a live Cotality field (annotation must name the field the value came FROM)`);
    if (built[k] !== v) error(5, `BUILD DRIFT: RESO_FIELD_MAP.${k} — source="${v}" vs built="${built[k] ?? '(absent)'}"`);
  }
  for (const k of Object.keys(built)) if (!(k in src)) error(5, `BUILD DRIFT: RESO_FIELD_MAP.${k} present in the built shell but not in the source module`);
  for (const field of REBNY_UCBA_RULES.removedFields) {
    if (new RegExp(`^(?!.*\\/\\/).*['"]${field}['"]`, 'm').test(sourceContent)) error(5, `reso-field-map.js: removed field "${field}" is active`);
  }
  for (const helper of ['resoAttr', 'resoData']) if (!builtContent.includes(`function ${helper}`)) error(5, `index-built.html: helper function ${helper}() not found`);
  log(`RESO_FIELD_MAP: ${Object.keys(src).length} annotation entries, all live or computed, source == built`);
}

// ═══════════════════════════════════════════════════════════════════════════
// SECTION 7: CONDITIONAL RULES — every REBNY_UCBA_RULES.conditionalRules requirement is collectable
// ═══════════════════════════════════════════════════════════════════════════
function validateConditionalRules(fileElements) {
  console.log('\n  Section 7: Conditional rules (REBNY_UCBA_RULES.conditionalRules) ...');
  for (const rule of REBNY_UCBA_RULES.conditionalRules) {
    for (const f of [...Object.keys(rule.appliesWhen), ...rule.requireFields]) {
      if (!isCanonical(f)) error(7, `rule ${rule.code} names "${f}", which is neither live nor a declared Mallan-internal key`);
    }
  }
  for (const data of Object.values(fileElements)) {
    if (data.config.category !== 'submission') continue;
    const skip = data.config.type === 'sale' ? RENTAL_ONLY : SALE_ONLY;
    const covered = new Set(data.elements.filter((e) => e.result.field).map((e) => e.result.field));
    for (const rule of REBNY_UCBA_RULES.conditionalRules) {
      const when = rule.appliesWhen;
      if (data.config.type === 'sale' && Array.isArray(when.PropertyType) && when.PropertyType.every((t) => /Lease/.test(t))) continue;
      if (data.config.type === 'rental' && Array.isArray(when.PropertyType) && !when.PropertyType.some((t) => /Lease/.test(t))) continue;
      const gaps = rule.requireFields.filter((f) => !skip.has(f) && !covered.has(f) && !SERVER_DERIVED.has(f) && !data.raw.includes(f));
      if (gaps.length) missing(`${data.fname}: ${rule.code} (${rule.description}) — not collectable: ${gaps.join(', ')}`);
      else log(`${data.fname}: ${rule.code} — collectable`);
    }
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// SECTION 8: ROLE MASKING (viewer files) — unchanged behaviour
// ═══════════════════════════════════════════════════════════════════════════
function validateRoleMasking(fileElements) {
  console.log('\n  Section 8: Role-based masking ...');
  const viewerChecks = [
    { key: 'saleViewer',   maskFn: 'applySaleRoleMasking',   defaultRole: 'buyer' },
    { key: 'rentalViewer', maskFn: 'applyRentalRoleMasking', defaultRole: 'tenant' },
  ];
  for (const { key, maskFn, defaultRole } of viewerChecks) {
    const data = fileElements[key]; if (!data) { error(8, `Cannot load ${key}`); continue; }
    const { raw, fname } = data;
    if (!raw.includes(`function ${maskFn}`)) error(8, `${fname}: ${maskFn}() function NOT FOUND`);
    if (!raw.includes('VIEWER_VALID_ROLES')) error(8, `${fname}: VIEWER_VALID_ROLES not found`);
    else for (const role of ['broker', 'agent', 'buyer', 'tenant', 'seller', 'landlord']) if (!raw.includes(`'${role}'`)) error(8, `${fname}: role "${role}" not in VIEWER_VALID_ROLES`);
    if (!raw.includes('isInsideSkipZone')) error(8, `${fname}: isInsideSkipZone() NOT FOUND`);
    if (!raw.includes(`'${defaultRole}'`) && !raw.includes(`"${defaultRole}"`)) warn(8, `${fname}: no default to "${defaultRole}" for unknown role (fail-closed)`);
    if (!raw.includes('_isLocal') && !raw.includes('IS_DEV') && !raw.includes('localhost')) error(8, `${fname}: no localhost/dev-mode check found`);
    if (!(raw.includes('Tab4') || raw.includes('tab4') || raw.includes('Distribution'))) warn(8, `${fname}: no evidence of hiding Distribution tab for restricted roles`);
    if (!(raw.includes('Tab6') || raw.includes('tab6') || raw.includes('History'))) warn(8, `${fname}: no evidence of hiding History tab for restricted roles`);
    if (!raw.includes('listing-agent-mask') && !raw.includes('agentMask') && !raw.includes('agent-mask')) error(8, `${fname}: no agent info masking CSS class found`);
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// SECTION 9: CANONICAL COVERAGE — how much of the REBNY contract each submission form can collect
// ═══════════════════════════════════════════════════════════════════════════
function validateCanonicalCoverage(fileElements) {
  console.log('\n  Section 9: Canonical coverage ...');
  const systemGenerated = new Set(REBNY_UCBA_RULES.requiredFields.systemGenerated);
  const contract = new Set([
    ...REBNY_UCBA_RULES.requiredFields.agentSubmitted.filter((f) => !systemGenerated.has(f) && !isMallanDecisionKey(f)),
    ...REBNY_UCBA_RULES.conditionalRules.flatMap((r) => r.requireFields),
  ]);
  for (const data of Object.values(fileElements)) {
    if (data.config.category !== 'submission') continue;
    const skip = data.config.type === 'sale' ? RENTAL_ONLY : SALE_ONLY;
    const bound = new Set(data.elements.filter((e) => e.result.field).map((e) => e.result.field));
    const applicable = [...contract].filter((f) => !skip.has(f));
    const covered = applicable.filter((f) => bound.has(f) || SERVER_DERIVED.has(f) || data.raw.includes(f));
    const live = [...bound].filter((f) => LIVE_FIELDS.has(f)).length;
    const internal = [...bound].filter((f) => INTERNAL_KEYS.has(f)).length;
    console.log(`    ${data.fname}: REBNY contract ${covered.length}/${applicable.length} collectable (${((covered.length / applicable.length) * 100).toFixed(1)}%) · bound controls: ${live} live Cotality fields, ${internal} Mallan-internal keys · Mallan controls: ${data.elements.filter((e) => e.result.internal).length}`);
  }
  console.log(`    live contract: ${LIVE_FIELDS.size} Property fields (pull ${liveContract.COTALITY_CONTRACT_PULLED_AT}) · REBNY required ${REBNY_UCBA_RULES.requiredFields.agentSubmitted.length} · conditional rules ${REBNY_UCBA_RULES.conditionalRules.length} · Mallan-internal keys ${INTERNAL_KEYS.size}`);
}

// ═══════════════════════════════════════════════════════════════════════════
// SECTION 10: VIEWER LOCKDOWN — unchanged behaviour
// ═══════════════════════════════════════════════════════════════════════════
function validateViewerLockdown(fileElements) {
  console.log('\n  Section 10: Viewer lockdown ...');
  for (const data of Object.values(fileElements)) {
    if (data.config.category !== 'viewer') continue;
    const { raw, fname } = data;
    if (!raw.includes('data-rls-viewer="true"')) error(10, `${fname}: <body> missing data-rls-viewer="true" attribute`);
    const formActions = raw.match(/<form[^>]*action=["'][^"']*["'][^>]*>/gi);
    if (formActions) for (const fa of formActions) {
      if (!fa.includes('action=""') && !fa.includes('action="#"') && !fa.includes('javascript:')) error(10, `${fname}: form has non-empty action attribute: ${fa.substring(0, 80)}`);
    }
    for (const { pattern, name } of [
      { pattern: /\bsubmitToRLS\b/g, name: 'submitToRLS()' },
      { pattern: /\bbuildRLSPayload\b/g, name: 'buildRLSPayload()' },
      { pattern: /\bfetch\s*\(\s*['"][^'"]*api/gi, name: 'fetch() to API endpoint' },
      { pattern: /\bXMLHttpRequest\b/g, name: 'XMLHttpRequest' },
    ]) {
      const matches = raw.match(pattern);
      if (matches) error(10, `${fname}: viewer contains ${name} (${matches.length}x) — not allowed in view-only file`);
    }
  }
}

// ═══════════════════════════════════════════════════════════════════════════
