  console.log(`    Mallan-internal keys: ${INTERNAL_KEYS.size} · form aliases accepted: ${Object.keys(FIELD_ALIASES).length} of ${Object.keys(RAW_ALIASES).length} · UI-only control ids: ${INTERNAL_ONLY_IDS.size}`);
