      const badgeText = errs > 0 ? `${errs} ERR` : miss > 0 ? `${miss} MISS` : warns > 0 ? `${warns} WARN` : 'PASS';
      html += `<div class="section"><h2>Section ${num}: ${esc(section.name)} <span class="badge ${badgeClass}">${badgeText}</span></h2>`;
